args.content:
interface User {
  id: number
  name: string
  isActive: boolean
}

interface UserStatsProps {
  users: User[]
}

export default function UserStats({ users }: UserStatsProps) {
  // Derived during render, same pattern as totalUsers in page.tsx
  const activeUsers = users.filter((user) => user.isActive).length
  const inactiveUsers = users.length - activeUsers
  const percentageOfActiveUsers =
    users.length === 0 ? 0 : Math.round((activeUsers / users.length) * 100)

  return (
    <div>
      <h2>User Statistics</h2>
      <p>Active users: {activeUsers}</p>
      <p>Inactive users: {inactiveUsers}</p>
      <p>Percentage of active users: {percentageOfActiveUsers}%</p>
    </div>
  )
}

